package org.beckenburg;

import javax.swing.*;
import java.awt.event.*;
import java.awt.image.BufferedImage;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import javax.imageio.ImageIO;
import org.beckenburg.editor.*;

public final class AssetImportTransformGuiTest {
    private static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    private static Object field(Object owner,String name)throws Exception{var f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}
    private static void await(java.util.function.BooleanSupplier condition)throws Exception{long end=System.nanoTime()+30_000_000_000L;while(System.nanoTime()<end){var done=new java.util.concurrent.atomic.AtomicBoolean();SwingUtilities.invokeAndWait(()->done.set(condition.getAsBoolean()));if(done.get())return;Thread.sleep(20);}throw new AssertionError("Human repair worker did not complete");}
    private static boolean ready(AssetImportDialog dock){try{return !((Boolean)field(dock,"busy"))&&((JButton)field(dock,"apply")).isEnabled();}catch(Exception e){throw new RuntimeException(e);}}
    private static boolean reviewed(AssetImportDialog dock){try{return !((Boolean)field(dock,"busy"))&&field(dock,"modelingPreview")!=null;}catch(Exception e){throw new RuntimeException(e);}}
    private static void button(AssetImportDialog dock,String name)throws Exception{((JButton)field(dock,name)).doClick();}
    private static void capture(AssetImportDialog dock,Path file)throws Exception{var content=((JDialog)field(dock,"dialog")).getContentPane();var image=new BufferedImage(content.getWidth(),content.getHeight(),BufferedImage.TYPE_INT_ARGB);var g=image.createGraphics();try{content.printAll(g);}finally{g.dispose();}ImageIO.write(image,"png",file.toFile());}
    private static JToggleButton tool(java.awt.Container parent,String name){for(var child:parent.getComponents()){if(child instanceof JToggleButton button&&button.getText().equals(name))return button;if(child instanceof java.awt.Container nested){var found=tool(nested,name);if(found!=null)return found;}}return null;}
    private static void runtime(String id,EditorTopologyProject project)throws Exception{
        var actual=GlbProps.model(id).triangles();var expected=project.mesh().triangles();check(actual.size()==expected.size(),"Actual transformed runtime triangle count");
        for(int i=0;i<actual.size();i++){var a=List.of(actual.get(i).a(),actual.get(i).b(),actual.get(i).c());var b=List.of(expected.get(i).a(),expected.get(i).b(),expected.get(i).c());for(int j=0;j<3;j++){var p=a.get(j);var q=b.get(j);check(p.x()==(double)(float)q.x()&&p.y()==(double)(float)q.y()&&p.z()==(double)(float)q.z()&&p.u()==(double)(float)q.u()&&p.v()==(double)(float)q.v(),"Every actual transformed runtime position/UV/winding");}}
        check(EditorTopologyProject.open(ImportedAssetLibrary.root().resolve(id+".authoring.btop")).snapshot().equals(project.snapshot()),"Runtime publication archives exact transformed native identities");
    }
    public static void main(String[] args)throws Exception{
        Path root=Files.createTempDirectory("human-transform-");String oldHome=System.getProperty("user.home");System.setProperty("user.home",root.toString());
        Path output=Path.of("build/editor-agent-evidence").toAbsolutePath();Files.createDirectories(output);Path source=root.resolve("triangle.obj");Files.writeString(source,"v 0 0 0\nv 1 0 0\nv 0 1 0\nvt .2 .3\nf 1/1 2/1 3/1\n");byte[] original=Files.readAllBytes(source);
        var ui=new AtomicReference<AssetImportDialog>();var project=new AtomicReference<EditorTopologyProject>();var published=new AtomicReference<String>();var before=new AtomicReference<EditorTopologyProject.State>();
        try{
            SwingUtilities.invokeAndWait(()->{var dock=new AssetImportDialog(null,published::set);ui.set(dock);try{((JDialog)field(dock,"dialog")).setVisible(true);}catch(Exception e){throw new RuntimeException(e);}dock.loadSource(source);});await(()->ready(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{var dock=ui.get();project.set((EditorTopologyProject)field(dock,"topologyProject"));before.set(project.get().snapshot());((JComboBox<?>)field(dock,"meshView")).setSelectedItem(EditorMeshPicking.Projection.FRONT);((JToggleButton)field(dock,"boxSelect")).setSelected(true);((JCheckBox)field(dock,"xraySelect")).setSelected(true);var canvas=(JPanel)field(dock,"preview");int x=dock.workingViewportWidth()-5,y=canvas.getHeight()-5;canvas.dispatchEvent(new MouseEvent(canvas,MouseEvent.MOUSE_PRESSED,System.currentTimeMillis(),0,5,5,1,false,MouseEvent.BUTTON1));canvas.dispatchEvent(new MouseEvent(canvas,MouseEvent.MOUSE_DRAGGED,System.currentTimeMillis(),InputEvent.BUTTON1_DOWN_MASK,x,y,0,false,MouseEvent.NOBUTTON));canvas.dispatchEvent(new MouseEvent(canvas,MouseEvent.MOUSE_RELEASED,System.currentTimeMillis(),0,x,y,1,false,MouseEvent.BUTTON1));}catch(Exception e){throw new RuntimeException(e);}});await(()->ready(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{var dock=ui.get();check(((Set<?>)field(dock,"selectedVertices")).size()==3,"Real X-ray selection chooses native vertices");tool((JDialog)field(dock,"dialog"),"Transform").doClick();((JComboBox<?>)field(dock,"meshView")).setSelectedItem(EditorMeshPicking.Projection.ISOMETRIC);((JComboBox<?>)field(dock,"transformAxis")).setSelectedItem("Y");((JComboBox<?>)field(dock,"transformPivot")).setSelectedIndex(1);((JSpinner)field(dock,"transformAmount")).setValue(92d);button(dock,"previewTransform");}catch(Exception e){throw new RuntimeException(e);}});await(()->reviewed(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{var dock=ui.get();var candidate=(EditorTopologyProject.EditPreview)field(dock,"modelingPreview");check(candidate.description().contains("90.0")&&project.get().snapshot()==before.get(),"Real angle snapping previews without mutation");capture(dock,output.resolve("mesh-rotation-preview.png"));button(dock,"cancelFaceEdit");check(project.get().snapshot()==before.get(),"Human transform Cancel");button(dock,"previewTransform");}catch(Exception e){throw new RuntimeException(e);}});await(()->reviewed(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{var dock=ui.get();var candidate=(EditorTopologyProject.EditPreview)field(dock,"modelingPreview");button(dock,"applyFaceEdit");check(project.get().snapshot()==candidate.snapshot(),"Apply exact native rotation");button(dock,"undoMesh");check(project.get().snapshot().equals(before.get()),"Human one-step rotation undo");button(dock,"redoMesh");check(project.get().snapshot().equals(candidate.snapshot()),"Human exact rotation redo");}catch(Exception e){throw new RuntimeException(e);}});await(()->ready(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{var dock=ui.get();((JComboBox<?>)field(dock,"transformKind")).setSelectedItem(EditorTopologyProject.Transform.SCALE_UNIFORM);((JSpinner)field(dock,"transformAmount")).setValue(2d);((JComboBox<?>)field(dock,"transformPivot")).setSelectedIndex(0);button(dock,"previewTransform");}catch(Exception e){throw new RuntimeException(e);}});await(()->reviewed(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{var dock=ui.get();var candidate=(EditorTopologyProject.EditPreview)field(dock,"modelingPreview");capture(dock,output.resolve("mesh-scale-preview.png"));button(dock,"applyFaceEdit");check(project.get().snapshot()==candidate.snapshot(),"Human scale installs exact native candidate");button(dock,"saveMesh");check(EditorTopologyProject.open(project.get().documentPath()).snapshot().equals(candidate.snapshot()),"Transformed native fresh open");}catch(Exception e){throw new RuntimeException(e);}});await(()->ready(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{button(ui.get(),"apply");}catch(Exception e){throw new RuntimeException(e);}});await(()->published.get()!=null);runtime(published.get(),project.get());check(Arrays.equals(original,Files.readAllBytes(source)),"Human transforms preserve original source");
            System.out.println("PASS actual human snapped rotation and centroid scale: real selection/buttons, preview/cancel/apply/history, native archive and every runtime corner");
        }finally{SwingUtilities.invokeAndWait(()->{if(ui.get()!=null)try{((JDialog)field(ui.get(),"dialog")).dispose();}catch(Exception e){throw new RuntimeException(e);}});System.setProperty("user.home",oldHome);try(var paths=Files.walk(root)){for(var path:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(path);}}
    }
}
